149	/**
150	 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
151	 * so tests can assert side-effects by reading that file — the second test-assertion channel
152	 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
153	 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
154	 *
155	 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
156	 * SYNC) so a test reads the record immediately.
157	 */
158	@Service
159	public class Audit {
160	
161	    private final Path file;
162	
163	    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
164	        this.file = Path.of(path);
165	    }
166	
167	    /** Append one audit record. Tests assert the exact line(s) in the file. */
168	    public synchronized void record(String entry) {
169	        try {
170	            Path parent = file.toAbsolutePath().getParent();
171	            if (parent != null) {
172	                Files.createDirectories(parent);
173	            }
174	            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
175	                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
176	        } catch (IOException e) {
177	            throw new UncheckedIOException(e);
178	        }
179	    }
180	
181	    /** Remove the audit file. */
182	    public synchronized void clear() {
183	        try {
184	            Files.deleteIfExists(file);
185	        } catch (IOException e) {
186	            throw new UncheckedIOException(e);
187	        }
188	    }
189	}
